/* One locally bundled school cursive for the entire classic app.
   This changes typography only. The explicit stroke models remain vector paths. */
const SCHOOL_TYPE_FAMILY='"Borel Lumi", cursive';
const SCHOOL_TYPE_CSS=`
@font-face{font-family:"Borel Lumi";src:url("assets/fonts/Borel-Regular.ttf") format("truetype");font-style:normal;font-weight:400;font-display:swap}
:root{--font-read:"Borel Lumi",cursive;--font-display:"Borel Lumi",cursive;--font-cursive:"Borel Lumi",cursive}
body,body *,body *::before,body *::after{font-family:"Borel Lumi",cursive!important;font-variant-ligatures:common-ligatures contextual!important;font-feature-settings:"liga" 1,"clig" 1,"calt" 1,"kern" 1!important;letter-spacing:0!important}
body{line-height:1.9}
button,input,select,textarea{font-family:"Borel Lumi",cursive!important;font-weight:400;line-height:1.8}
svg text,svg tspan{font-family:"Borel Lumi",cursive!important}
h1,h2,h3,h4,.brand b,.who-card b,.av-name,.theme-name,.simple-game b,.tile b,.world b,.section-title,.prompt,.celebrate h2,.theme-welcome h1,.theme-heading h1{line-height:1.8!important;font-weight:400!important;overflow:visible}
p,label,output,.caption,.completion-note,.defi-note,.narrative-prompt,.game-voice-status,.game-level-name,.node-row .lab,.character-pair-count{line-height:1.85!important}
.brand b{font-size:clamp(17px,2.3vw,25px);white-space:normal}
.theme-name{font-size:clamp(23px,3.3vw,31px)}
.theme-welcome h1,.theme-heading h1{font-size:clamp(25px,3.5vw,34px)}
.simple-game b{font-size:21px;max-width:100%;overflow-wrap:anywhere}
.theme-card,.simple-game{gap:10px;padding-top:18px;padding-bottom:23px}
.who-head h1{font-size:clamp(27px,4.5vw,43px);line-height:1.8}
.who-card b{font-size:clamp(29px,4.8vw,45px)}
.who-head p,.who-sub,.theme-welcome p{line-height:1.85}
.btn-play,.pbtn,.go-btn,.hint-btn,.celebrate .acts button,.game-level-button,.skip-exercise,.u-btn{line-height:1.8!important;padding-top:.25em;padding-bottom:.6em;white-space:normal}
.lvl,.chip,.reward-counter,.av-lvl{line-height:1.8;overflow:visible}
.lvl{padding:5px 12px 10px;font-size:14px;white-space:normal}
.game-level-progress{padding-top:1px;padding-bottom:7px;min-height:45px}
.game-level-name{white-space:normal;max-height:none;overflow:visible;text-overflow:clip}
.game-bottom{min-height:104px;align-items:center}
.caption{font-size:clamp(14px,1.7vw,17px);overflow-wrap:anywhere;padding:.1em 0 .35em}
.game-bottom .voice-tools{flex-wrap:wrap}
.stage{overflow:auto}
.stage.upgrade-stage{justify-content:flex-start!important}
.reading-practice-stage .upgrade-wrap{gap:8px}
.reading-practice-stage .read-act-sentence{font-size:clamp(21px,3vw,29px)}
.reading-practice-stage .read-act-scene{height:min(270px,33vh)}
.stage>:first-child{margin-top:auto}
.stage>:last-child{margin-bottom:auto}
.prompt{font-size:clamp(21px,3.1vw,31px)}
.grapheme{font-size:clamp(60px,10vw,92px)!important;line-height:1.75!important;font-weight:400!important;overflow:visible}
.gcard{padding:4px 22px 12px;gap:clamp(12px,2vw,24px);max-width:100%;flex-wrap:wrap;justify-content:center;overflow:visible}
.gcard .alt{font-size:clamp(34px,5.5vw,56px)!important}
.word{font-size:clamp(35px,6.5vw,64px);line-height:1.8!important;font-weight:400;overflow:visible;display:inline-block}
.word>.s0,.word>.s1,.word .s0>span,.word .s1>span{display:inline}
.sent,.sentence,.book-page p,.book-word,.reading-word{line-height:1.9!important}
.card{line-height:1.65;overflow:visible}
.card.txt{font-size:clamp(34px,6vw,62px);font-weight:400;padding:8px 14px 17px}
.mcard .b.word{line-height:1.8;font-size:clamp(18px,2.5vw,25px);padding:.15em .15em .45em;overflow:visible}
.slot,.ltile{height:auto!important;min-height:clamp(72px,11vw,105px);font-size:clamp(29px,5vw,43px)!important;line-height:1.75!important;font-weight:400!important;padding:.04em .3em .35em;overflow:visible}
.fusion{font-size:clamp(42px,8vw,80px);line-height:1.75}
.fusion .c,.fusion .v{padding:3px 18px 15px}
.big-num{font-size:clamp(52px,10vw,96px);line-height:1.65}
.eq{font-size:clamp(32px,6vw,58px);line-height:1.75;overflow:visible}
.keypad button{height:auto;min-height:58px;line-height:1.7;font-size:clamp(23px,3.5vw,30px);padding:3px 10px 13px;overflow:visible}
.node{font-size:32px;line-height:1.75;padding-bottom:8px;overflow:visible}
.seqnum{line-height:1.75;padding:1px 14px 10px}
.nline .tl,.sbtn .n,.field .obj.counted::after{line-height:1.8}
.school-writing-transfer{line-height:1.85}
.school-writing-transfer .school-cursive-model{font-size:27px;line-height:1.85}
@media(max-height:760px) and (min-width:601px){
 .game-top{padding-top:6px}.game-bottom{min-height:96px;padding-top:3px;padding-bottom:7px}.game-level-progress{min-height:39px;padding-bottom:3px}.stage{gap:12px;padding-top:12px;padding-bottom:16px}.grapheme{font-size:78px!important}.gcard .alt{font-size:46px!important}.card.txt{font-size:clamp(32px,5vw,52px)}.prompt{font-size:26px}.celebrate h2{font-size:42px}.theme-welcome{padding-top:16px;padding-bottom:12px}
}
@media(max-width:600px){
 body{font-size:16px}.brand b{font-size:17px}.theme-name{font-size:24px}.simple-game b{font-size:19px}.theme-card,.theme-card:nth-child(-n+2){padding:15px 10px 21px;gap:9px}.simple-game{min-height:190px;padding:16px 10px 22px}.theme-heading{gap:13px}.theme-heading h1{font-size:25px}.game-level-progress{min-height:42px;gap:6px}.game-level-name{font-size:12px}.game-bottom{min-height:112px;gap:8px}.caption{font-size:14px}.skip-exercise{font-size:12px}.grapheme{font-size:66px!important}.gcard .alt{font-size:38px!important}.gcard{padding:2px 16px 10px;gap:10px}.word{font-size:clamp(33px,7vw,44px)}.slot,.ltile{font-size:31px!important;min-height:79px}.card.txt{font-size:clamp(30px,6vw,42px)}.keypad button{min-height:58px;font-size:25px}.prompt{font-size:23px}.celebrate h2{font-size:32px}.celebrate .acts button{font-size:19px}.who-head h1{font-size:30px}.who-card b{font-size:35px}
}
`;
function installSchoolType(){
 if(typeof document==='undefined'||!document.head)return;
 if(document.querySelector&&document.querySelector('#school-type-style'))return;
 const style=document.createElement('style');style.id='school-type-style';style.setAttribute('id','school-type-style');style.textContent=SCHOOL_TYPE_CSS;document.head.append(style);
 if(document.documentElement)document.documentElement.setAttribute('data-school-type','borel-cursive');
}
installSchoolType();

/* Self-contained lettering in downloaded cards and paper worksheets. */
const SCHOOL_EXPORT_FONT="data:font/ttf;base64,";
function schoolTypeSVG(svg){return svg.replace(/(<svg\b[^>]*>)/,'$1<style>@font-face{font-family:"Borel Lumi";src:url("'+SCHOOL_EXPORT_FONT+'") format("truetype")}text,tspan{font-family:"Borel Lumi",cursive!important;font-weight:400!important;letter-spacing:0!important}</style>');}
const schoolVisitBefore=visitSVG;visitSVG=c=>schoolTypeSVG(schoolVisitBefore(c));
const schoolSheetBefore=schoolWritingWorksheetSVG;schoolWritingWorksheetSVG=(...args)=>schoolTypeSVG(schoolSheetBefore(...args));
const schoolLegacySheetBefore=writingWorksheetSVG;writingWorksheetSVG=(...args)=>schoolTypeSVG(schoolLegacySheetBefore(...args));
